<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue';
import { NAlert, NButton, NCard, NFormItem, NInput, NModal, NRadioButton, NRadioGroup, NSpace, NSpin, NSwitch, NTag, useMessage } from 'naive-ui';
import { native, request } from '../api';
import { useRuntime } from '../stores/runtime';

declare global { interface Window { QRCode?: { toDataURL:(text:string,options?:Record<string,unknown>)=>Promise<string> } } }
const runtime=useRuntime();const message=useMessage();const loading=ref(true);const error=ref('');const busy=ref(false);const platforms=ref<any[]>([]);
const configModal=ref(false);const selected=ref<any>(null);const form=reactive<Record<string,string>>({});
const qrModal=ref(false);const qrPlatform=ref<'telegram'|'whatsapp'|'feishu'|'weixin'|'qqbot'>('telegram');const qrPhase=ref('idle');const qrError=ref('');const qrImage=ref('');const qrSession=ref<any>(null);const allowed=ref('');const whatsappMode=ref('bot');const feishuDomain=ref('feishu');const feishuDmPolicy=ref('pairing');const feishuGroupPolicy=ref('open');const feishuAllowedUsers=ref('');const feishuHomeChannel=ref('');const chatDmPolicy=ref('pairing');const chatGroupPolicy=ref('disabled');const chatAllowedUsers=ref('');const chatGroupAllowed=ref('');const chatHomeChannel=ref('');let pollTimer:ReturnType<typeof setTimeout>|undefined;let qrCompleting=false;
// host 驱动：feishu/weixin/qqbot 走宿主 api/host/messaging/...（Node 侧驱动协议 + 一次性 python apply）
function isHostPlatform(p:string){return p==='feishu'||p==='weixin'||p==='qqbot';}
const canScan=computed(()=>['telegram','whatsapp','feishu','weixin','qqbot'].includes(selected.value?.id));
// 后端（Hermes 工作服务 / Dashboard 9219）不可用时，native 调用会 502/503 报 "unavailable"。
// 此时不显示冷冰冰的原始错误，而是给诊断卡片 + "启动工作服务" 按钮。
const backendDown=computed(()=>!!error.value && (/unavailable|502|503|ECONNREFUSED|拒绝连接|代理不可用|backend/i.test(error.value) || (runtime.status?.backend?.state && runtime.status.backend.state!=='ready' && runtime.status.backend.state!=='starting')));
async function startBackend(){try{await runtime.service('start');message.success('已提交启动工作服务，请稍候刷新');await load();}catch(e){message.error((e as Error).message);}}
const qrAdvice=computed(()=>{if(!qrError.value)return'';if(qrPlatform.value==='telegram')return'这是 Hermes 官方远端配对服务返回的错误。可以稍后重试，或使用 Bot Token 手动配置。';if(qrPlatform.value==='feishu')return'这是 Hermes 原生飞书自动建机器人服务返回的错误。请确认 NAS 可以访问飞书或 Lark 账号服务，也可暂时使用 App ID 和 App Secret 手动配置。';if(qrPlatform.value==='weixin')return'这是腾讯 iLink 服务返回的错误。请确认 NAS 可以访问 ilinkai.weixin.qq.com，也可在「手动配置」里填入 iLink 账号 ID 与 Token。';if(qrPlatform.value==='qqbot')return'这是 QQ 机器人绑定服务返回的错误。请确认 NAS 可以访问 q.qq.com，也可在「手动配置」里填入 App ID 与 App Secret。';if(/install|dependencies|download|python/i.test(qrError.value))return'首次接入需要下载 WhatsApp bridge 运行依赖。请确认 NAS 可以访问依赖下载源；仍失败时运行 hermes pm doctor 后重试。';return'请检查网络和 Hermes 通讯网关日志后重试。';});
async function load(){const owner=runtime.profile;loading.value=true;error.value='';try{const result:any=await native('/api/messaging/platforms',owner);if(owner===runtime.profile)platforms.value=result.platforms||[];}catch(e){if(owner===runtime.profile)error.value=(e as Error).message;}finally{if(owner===runtime.profile)loading.value=false;}}
watch(()=>runtime.profile,()=>{configModal.value=false;void cancelQr();void load();});onMounted(()=>void load());onBeforeUnmount(()=>{if(pollTimer)clearTimeout(pollTimer);void cancelQr();});
function openConfig(row:any){selected.value=row;Object.keys(form).forEach(key=>delete form[key]);for(const field of row.env_vars||[])form[field.key]=field.is_password?'':field.value||'';configModal.value=true;}
async function saveConfig(){if(!selected.value)return;const env:Record<string,string>={};for(const field of selected.value.env_vars||[]){const value=form[field.key]?.trim();if(field.is_password?!value:value===(field.value||''))continue;if(value)env[field.key]=value;}busy.value=true;try{await native(`/api/messaging/platforms/${encodeURIComponent(selected.value.id)}`,runtime.profile,'PUT',{env});message.success('通讯配置已保存');configModal.value=false;await load();}catch(e){message.error((e as Error).message);}finally{busy.value=false;}}
async function toggle(row:any,enabled:boolean){busy.value=true;try{await native(`/api/messaging/platforms/${encodeURIComponent(row.id)}`,runtime.profile,'PUT',{enabled});message.success(enabled?'平台已启用':'平台已停用');await load();}catch(e){message.error((e as Error).message);}finally{busy.value=false;}}
async function test(row:any){busy.value=true;try{const result:any=await native(`/api/messaging/platforms/${encodeURIComponent(row.id)}/test`,runtime.profile,'POST');(result.ok?message.success:message.warning)(result.message||result.state||'测试完成');await load();}catch(e){message.error((e as Error).message);}finally{busy.value=false;}}
async function renderQr(value:string){if(!window.QRCode?.toDataURL)throw new Error('二维码组件未加载，请刷新页面重试');qrImage.value=await window.QRCode.toDataURL(value,{errorCorrectionLevel:'M',margin:2,width:240,color:{dark:'#111827',light:'#ffffff'}});}
function openQr(row:any){selected.value=row;qrPlatform.value=row.id;qrModal.value=true;qrPhase.value='idle';qrError.value='';qrImage.value='';qrSession.value=null;allowed.value='';whatsappMode.value=row.whatsapp_setup?.mode||'bot';feishuDomain.value='feishu';feishuDmPolicy.value='pairing';feishuGroupPolicy.value='open';feishuAllowedUsers.value='';feishuHomeChannel.value='';chatDmPolicy.value='pairing';chatGroupPolicy.value='disabled';chatAllowedUsers.value='';chatGroupAllowed.value='';chatHomeChannel.value='';if(row.id==='telegram'||row.id==='weixin'||row.id==='qqbot')void beginQr();}
async function beginQr(){if(!selected.value)return;qrPhase.value='starting';qrError.value='';qrImage.value='';qrSession.value=null;try{let result:any;if(qrPlatform.value==='feishu'){result=await request('api/host/messaging/feishu/onboarding/start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({domain:feishuDomain.value})});}else if(qrPlatform.value==='weixin'||qrPlatform.value==='qqbot'){result=await request(`api/host/messaging/${qrPlatform.value}/onboarding/start`,{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});}else{const body=qrPlatform.value==='telegram'?{bot_name:'Hermes Agent'}:{mode:whatsappMode.value,allowed_users:'',profile:runtime.profile};result=await native(`/api/messaging/${qrPlatform.value}/onboarding/start`,runtime.profile,'POST',body);}qrSession.value=result;if(result.qr_payload)await renderQr(result.qr_payload);if(qrPlatform.value==='whatsapp'&&result.status==='connected')qrPhase.value='ready';else{qrPhase.value='waiting';schedulePoll();}}catch(e){qrPhase.value='error';qrError.value=(e as Error).message;}}
function schedulePoll(){if(pollTimer)clearTimeout(pollTimer);pollTimer=setTimeout(()=>void pollQr(),Math.max(1200,Number(qrSession.value?.poll_after_ms)||1500));}
async function pollQr(){const session=qrSession.value;if(!session||!qrModal.value)return;try{const hostP=isHostPlatform(qrPlatform.value)&&qrPlatform.value!=='feishu'?qrPlatform.value:null;const result:any=(qrPlatform.value==='feishu')?await request(`api/host/messaging/feishu/onboarding/${encodeURIComponent(session.pairing_id)}`):hostP?await request(`api/host/messaging/${hostP}/onboarding/${encodeURIComponent(session.pairing_id)}`):await native(`/api/messaging/${qrPlatform.value}/onboarding/${encodeURIComponent(session.pairing_id)}`,runtime.profile);qrSession.value={...session,...result};if(result.qr_payload&&result.qr_payload!==session.qr_payload)await renderQr(result.qr_payload);const ready=qrPlatform.value==='telegram'?result.status==='ready':qrPlatform.value==='whatsapp'?result.status==='connected':result.status==='ready';if(ready){qrPhase.value='ready';if(result.owner_user_id)allowed.value=result.owner_user_id;return;}if(['error','cancelled','expired'].includes(result.status))throw new Error(result.error||'扫码接入会话已结束，请重新开始');qrPhase.value='waiting';schedulePoll();}catch(e){qrError.value=(e as Error).message;qrPhase.value='error';}}
async function applyQr(){const session=qrSession.value;if(!session)return;const ids=allowed.value.split(',').map(v=>v.trim()).filter(Boolean);if(qrPlatform.value==='telegram'&&!ids.length)return message.error('请填写允许使用机器人的 Telegram 用户 ID');if(qrPlatform.value==='feishu'&&feishuDmPolicy.value==='allowlist'&&!feishuAllowedUsers.value.trim())return message.error('请填写允许使用机器人的飞书用户 ID');if(qrPlatform.value==='weixin'&&chatDmPolicy.value==='allowlist'&&!chatAllowedUsers.value.trim())return message.error('请填写允许使用微信的用户 ID');if(qrPlatform.value==='qqbot'&&chatDmPolicy.value==='allowlist'&&!chatAllowedUsers.value.trim())return message.error('请填写允许使用 QQ 的用户 OpenID');busy.value=true;try{qrCompleting=true;if(qrPlatform.value==='feishu'){const result:any=await request(`api/host/messaging/feishu/onboarding/${encodeURIComponent(session.pairing_id)}/apply`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({profile:runtime.profile,dm_policy:feishuDmPolicy.value,allowed_users:feishuAllowedUsers.value,group_policy:feishuGroupPolicy.value,home_channel:feishuHomeChannel.value})});message.success(result.restart_started?'飞书机器人已自动创建并保存，通讯网关正在重启':'飞书机器人已自动创建并保存，请重启通讯网关后使用');}else if(qrPlatform.value==='weixin'||qrPlatform.value==='qqbot'){const name=qrPlatform.value==='weixin'?'微信':'QQ';const result:any=await request(`api/host/messaging/${qrPlatform.value}/onboarding/${encodeURIComponent(session.pairing_id)}/apply`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({profile:runtime.profile,dm_policy:chatDmPolicy.value,allowed_users:chatAllowedUsers.value,group_policy:chatGroupPolicy.value,group_allowed_users:chatGroupAllowed.value,home_channel:chatHomeChannel.value})});message.success(result.restart_started?`${name}机器人已保存，通讯网关正在重启`:`${name}机器人已保存，请重启通讯网关后使用`);}else{const body=qrPlatform.value==='telegram'?{allowed_user_ids:ids,profile:runtime.profile}:{mode:whatsappMode.value,allowed_users:allowed.value,profile:runtime.profile};await native(`/api/messaging/${qrPlatform.value}/onboarding/${encodeURIComponent(session.pairing_id)}/apply`,runtime.profile,'POST',body);message.success('扫码接入已保存，Hermes 会按原生流程重启通讯网关');}qrSession.value=null;qrModal.value=false;await load();}catch(e){qrCompleting=false;message.error((e as Error).message);}finally{busy.value=false;}}
async function cancelQr(){if(pollTimer)clearTimeout(pollTimer);pollTimer=undefined;const session=qrSession.value;qrSession.value=null;if(session&&!qrCompleting){try{if(qrPlatform.value==='feishu')await request(`api/host/messaging/feishu/onboarding/${encodeURIComponent(session.pairing_id)}`,{method:'DELETE'});else if(qrPlatform.value==='weixin'||qrPlatform.value==='qqbot')await request(`api/host/messaging/${qrPlatform.value}/onboarding/${encodeURIComponent(session.pairing_id)}`,{method:'DELETE'});else await native(`/api/messaging/${qrPlatform.value}/onboarding/${encodeURIComponent(session.pairing_id)}`,runtime.profile,'DELETE');}catch{}}qrCompleting=false;qrImage.value='';qrPhase.value='idle';}
watch(qrModal,value=>{if(!value)void cancelQr();});
</script>

<template>
  <div class="toolbar"><span class="muted">Hermes 原生通讯平台 · Profile {{ runtime.profile }}</span><n-button @click="load">刷新状态</n-button></div>
  <n-card v-if="backendDown" :bordered="false" class="mb messaging-diag">
    <div class="messaging-diag-head"><h3>通讯后端当前不可用（Dashboard unavailable）</h3><n-button size="small" type="primary" :loading="runtime.busy" @click="startBackend">启动工作服务</n-button></div>
    <p class="muted">读取通讯平台需要 Hermes 工作服务（Dashboard，端口 9219）在线。请先在「概览」页启动工作服务，或点击上方按钮；若已启动仍不可用，请检查「运行日志」中 <code>dashboard</code> 来源的报错。原始错误：{{ error }}</p>
  </n-card>
  <n-alert v-else-if="error" type="error" :bordered="false" class="mb">{{ error }}</n-alert>
  <div v-if="loading" class="state"><n-spin size="small"/>正在读取通讯平台…</div>
  <div v-else class="resource-list"><n-card v-for="row in platforms" :key="row.id" :bordered="false"><div class="split"><div class="resource-description"><h3>{{ row.name }} <n-tag size="small" :type="row.state==='connected'?'success':row.configured?'warning':'default'" :bordered="false">{{ row.state==='connected'?'已连接':row.configured?'已配置':'未配置' }}</n-tag></h3><p>{{ row.description||row.error_message||'由 Hermes 原生消息网关管理' }}</p><span v-if="row.gateway_running" class="muted">通讯网关运行中</span></div><n-space align="center"><n-button v-if="['telegram','whatsapp','feishu','weixin','qqbot'].includes(row.id)" size="small" type="primary" secondary @click="openQr(row)">{{ ['feishu','weixin'].includes(row.id)?'扫码自动配置':row.id==='qqbot'?'扫码添加机器人':'扫码接入' }}</n-button><n-button size="small" @click="openConfig(row)">手动配置</n-button><n-button size="small" :disabled="!row.configured" @click="test(row)">测试</n-button><n-switch :value="row.enabled" :disabled="busy" @update:value="value=>toggle(row,value)"/></n-space></div></n-card></div>

  <n-modal v-model:show="configModal" preset="card" :title="`${selected?.name||''} 手动配置`" style="width:600px;max-width:calc(100vw - 32px)"><p class="muted mb">字段与验证规则来自 Hermes 原生平台目录。密码留空时保留已有值。</p><n-form-item v-for="field in selected?.env_vars||[]" :key="field.key" :label="field.prompt||field.description||field.key"><n-input v-model:value="form[field.key]" :type="field.is_password?'password':'text'" show-password-on="click" :placeholder="field.is_password&&field.is_set?'已配置，留空保留原值':field.key"/><template #feedback><code>{{ field.key }}</code></template></n-form-item><n-alert v-if="canScan" type="info" :bordered="false">Telegram、WhatsApp、Feishu / Lark、Weixin（微信）与 QQ 机器人均支持 Hermes 原生扫码接入；扫码后会自动创建机器人并保存凭据。</n-alert><template #footer><div class="modal-footer"><n-button @click="configModal=false">取消</n-button><n-button type="primary" :loading="busy" @click="saveConfig">保存</n-button></div></template></n-modal>

  <n-modal v-model:show="qrModal" preset="card" :title="qrPlatform==='telegram'?'Telegram 扫码接入':qrPlatform==='whatsapp'?'WhatsApp 扫码接入':qrPlatform==='weixin'?'微信扫码接入微信机器人':qrPlatform==='qqbot'?'QQ 扫码添加机器人':'Feishu / Lark 扫码自动配置'" style="width:640px;max-width:calc(100vw - 32px)">
    <template v-if="qrPhase==='idle'">
      <n-form-item v-if="qrPlatform==='whatsapp'" label="模式"><n-radio-group v-model:value="whatsappMode"><n-radio-button value="bot">机器人模式</n-radio-button><n-radio-button value="self-chat">给自己发消息</n-radio-button></n-radio-group></n-form-item>
      <template v-if="qrPlatform==='feishu'"><n-alert type="info" :bordered="false" class="mb">使用 Hermes 原生 device-code 流程。扫码授权后，飞书会自动创建并配置机器人，App Secret 不会发送到浏览器。</n-alert><n-form-item label="账号区域"><n-radio-group v-model:value="feishuDomain"><n-radio-button value="feishu">飞书（中国）</n-radio-button><n-radio-button value="lark">Lark（国际）</n-radio-button></n-radio-group></n-form-item></template>
      <template v-if="qrPlatform==='weixin'||qrPlatform==='qqbot'"><n-alert type="info" :bordered="false" class="mb">{{ qrPlatform==='weixin'?'使用微信扫描二维码并确认，iLink 会自动创建机器人并保存账号凭据。凭据保存在本地 Hermes Home，不会上传到服务器。':'使用 QQ 扫描二维码并确认，会自动添加机器人并保存 App 凭据。凭据保存在本地 Hermes Home。' }}</n-alert></template>
    </template>
    <n-alert v-if="qrError" type="error" :bordered="false" class="mb"><div class="qr-error-detail">{{ qrError }}</div><div class="qr-error-advice">{{ qrAdvice }}</div></n-alert>
    <div v-if="qrPhase==='starting'" class="state"><n-spin/>正在创建 Hermes 原生配对会话…</div>
    <template v-else-if="qrPhase!=='idle'"><div v-if="qrImage" class="qr-box"><img :src="qrImage" alt="扫码二维码"/></div><p class="muted" style="text-align:center">{{ qrPhase==='ready'?(qrPlatform==='feishu'?`已创建${qrSession?.bot_name?'机器人「'+qrSession.bot_name+'」':'飞书机器人'}，请选择访问策略后保存。`:qrPlatform==='weixin'?'微信已扫码确认，请选择访问策略后保存。':qrPlatform==='qqbot'?'QQ 已扫码添加机器人，请选择访问策略后保存。':'设备已经确认，请完成授权保存。'):qrPlatform==='telegram'?'使用 Telegram 扫码并按提示创建机器人。':qrPlatform==='feishu'?'使用飞书或 Lark 扫码并确认自动创建机器人。':qrPlatform==='weixin'?'请使用微信扫描二维码并确认。':qrPlatform==='qqbot'?'请使用 QQ 扫描二维码并确认。':`正在准备 WhatsApp 二维码（${qrSession?.status||'waiting'}）…` }}</p>
      <template v-if="qrPlatform==='feishu'&&qrPhase==='ready'"><n-form-item label="私信访问"><n-radio-group v-model:value="feishuDmPolicy"><n-radio-button value="pairing">配对审批（推荐）</n-radio-button><n-radio-button value="open">允许所有人</n-radio-button><n-radio-button value="allowlist">仅指定用户</n-radio-button></n-radio-group></n-form-item><n-form-item v-if="feishuDmPolicy==='allowlist'" label="允许的用户 ID"><n-input v-model:value="feishuAllowedUsers" placeholder="ou_xxx，多个用逗号分隔"/></n-form-item><n-form-item label="群聊"><n-radio-group v-model:value="feishuGroupPolicy"><n-radio-button value="open">仅被 @ 时回复</n-radio-button><n-radio-button value="disabled">禁用群聊</n-radio-button></n-radio-group></n-form-item><n-form-item label="默认会话 ID（可选）"><n-input v-model:value="feishuHomeChannel" placeholder="用于定时任务和通知，可留空"/></n-form-item></template>
      <template v-else-if="(qrPlatform==='weixin'||qrPlatform==='qqbot')&&qrPhase==='ready'"><n-form-item label="私信访问"><n-radio-group v-model:value="chatDmPolicy"><n-radio-button value="pairing">配对审批（推荐）</n-radio-button><n-radio-button value="open">允许所有人</n-radio-button><n-radio-button value="allowlist">仅指定用户</n-radio-button><n-radio-button v-if="qrPlatform==='weixin'" value="disabled">禁用私信</n-radio-button></n-radio-group></n-form-item><n-form-item v-if="chatDmPolicy==='allowlist'" label="允许的用户 ID"><n-input v-model:value="chatAllowedUsers" :placeholder="qrPlatform==='weixin'?'微信用户 ID，多个用逗号分隔':'QQ 用户 OpenID，多个用逗号分隔'"/></n-form-item><template v-if="qrPlatform==='weixin'"><n-form-item label="群聊"><n-radio-group v-model:value="chatGroupPolicy"><n-radio-button value="disabled">禁用群聊（推荐）</n-radio-button><n-radio-button value="open">允许所有群聊</n-radio-button><n-radio-button value="allowlist">仅指定群 ID</n-radio-button></n-radio-group></n-form-item><n-form-item v-if="chatGroupPolicy==='allowlist'" label="允许的群 ID"><n-input v-model:value="chatGroupAllowed" placeholder="群聊 ID，多个用逗号分隔"/></n-form-item></template><n-form-item label="默认会话 ID（可选）"><n-input v-model:value="chatHomeChannel" :placeholder="qrPlatform==='weixin'?'用于定时任务和通知，可留空':'用于定时任务和通知，可留空'"/></n-form-item></template>
      <n-form-item v-else-if="qrPhase==='ready'||qrPlatform==='whatsapp'" :label="qrPlatform==='telegram'?'允许的 Telegram 用户 ID（逗号分隔）':'允许的 WhatsApp 号码（逗号分隔，可留空走配对审批）'" class="mt"><n-input v-model:value="allowed" placeholder="例如 123456789"/></n-form-item>
    </template>
    <template #footer><div class="modal-footer"><n-button @click="qrModal=false">关闭</n-button><n-button v-if="qrPhase==='idle'" type="primary" @click="beginQr">生成二维码</n-button><n-button v-if="qrPhase==='error'&&(qrPlatform==='telegram'||qrPlatform==='weixin'||qrPlatform==='qqbot')" @click="qrModal=false;selected&&openConfig(selected)">手动配置</n-button><n-button v-if="qrPhase==='error'" @click="beginQr">重新开始</n-button><n-button v-if="qrPhase==='ready'" type="primary" :loading="busy" @click="applyQr">保存并接入</n-button></div></template>
  </n-modal>
</template>
